namespace PoloOS.Diagnostics.Core;
public sealed class PoloDiagnosticsScanner
{
    public static readonly ModuleSpec[] DefaultModules=[new(0x01,"Motor",9600),new(0x03,"ABS",10400),new(0x08,"Klima",10400),new(0x09,"Merkezi Elektrik",10400),new(0x15,"Airbag",10400),new(0x17,"Gösterge",10400),new(0x25,"İmmobilizer",10400),new(0x44,"Direksiyon",10400)]; private readonly int _deviceIndex; private readonly DiagLog _log; public PoloDiagnosticsScanner(int deviceIndex,DiagLog log){_deviceIndex=deviceIndex;_log=log;}
    public ModuleScanResult Scan(ModuleSpec module){var candidates=BuildWakeCandidates(module);Exception? lastError=null;foreach(var candidate in candidates)for(var retry=1;retry<=3;retry++){_log.Write($"SCAN_ATTEMPT addr={module.Address:X2} {module.Name} baud={module.Baud} parity={(candidate.Even?"EVEN":"ODD")} bitMs={candidate.BitMs} retry={retry}/3");try{using var transport=new FtdiD2xxTransport(_deviceIndex,_log);transport.Open(module.Baud);var common=new KwpCommon(transport,_log);var wake=common.WakeUp(module.Address,candidate.Even,candidate.BitMs);if(wake.KeywordVersion>=2000){var targetCandidates=module.Address==0x03?new byte[]{0x28,0x03,0x10}:new byte[]{module.Address};Exception? kwLast=null;foreach(var target in targetCandidates){var kw2000=new Kwp2000Dialog(common,module.Address,_log,target);try{var identMsg=kw2000.ReadIdentification91();var identHex=string.Join(" ",identMsg.Body.Select(x=>x.ToString("X2")));var dtcs=kw2000.ReadStoredFaultCodes();return new ModuleScanResult(module,true,VagProtocol.Kwp2000,wake.KeywordVersion,$"KW{wake.KeywordVersion} target={target:X2} ident={identHex}",dtcs,dtcs.Count==0?"HATA KODU YOK":$"{dtcs.Count} DTC OKUNDU",$"{candidate.BitMs}ms/{(candidate.Even?"EVEN":"ODD")}");}catch(Exception exTarget){kwLast=exTarget;_log.Write($"KWP2000_TARGET_FAIL target={target:X2} reason={exTarget.GetType().Name}: {exTarget.Message}");}}try{var kw2000=new Kwp2000Dialog(common,module.Address,_log,0x28);var ident=kw2000.SendReceiveUnaddressed(0x1A,0x91);var identHex=string.Join(" ",ident.Body.Select(x=>x.ToString("X2")));var dtcMsg=kw2000.SendReceiveUnaddressed(0x18,0x02,0xFF,0x00);var dtcs=ParseKwp2000DtcForScanner(dtcMsg);return new ModuleScanResult(module,true,VagProtocol.Kwp2000,wake.KeywordVersion,$"KW{wake.KeywordVersion} unaddressed ident={identHex}",dtcs,dtcs.Count==0?"HATA KODU YOK":$"{dtcs.Count} DTC OKUNDU",$"{candidate.BitMs}ms/{(candidate.Even?"EVEN":"ODD")}");}catch(Exception unaddr){throw new InvalidOperationException($"KW{wake.KeywordVersion} wake OK but all KWP2000 targets failed. LastTarget={kwLast?.Message}; Unaddressed={unaddr.Message}");}}
        if(wake.KeywordVersion==1281){var dialog=new Kw1281Dialog(common,_log);var startup=dialog.Connect();var ident=string.Join(" | ",startup.Where(b=>b.Title==0xF6&&!string.IsNullOrWhiteSpace(b.Ascii)).Select(b=>b.Ascii).Distinct());var dtcs=dialog.ReadFaultCodes();return new ModuleScanResult(module,true,VagProtocol.Kwp1281,wake.KeywordVersion,ident,dtcs,dtcs.Count==0?"HATA KODU YOK":$"{dtcs.Count} DTC OKUNDU",$"{candidate.BitMs}ms/{(candidate.Even?"EVEN":"ODD")}");}throw new InvalidOperationException($"Unsupported keyword version {wake.KeywordVersion}.");}catch(Exception ex){lastError=ex;_log.Write($"SCAN_FAIL addr={module.Address:X2} retry={retry}/3 reason={ex.GetType().Name}: {ex.Message}");Thread.Sleep(1200);}}return new ModuleScanResult(module,false,VagProtocol.Unknown,0,string.Empty,Array.Empty<DtcEntry>(),lastError?.Message??"CEVAP YOK","-");}
    public IReadOnlyList<ModuleScanResult> ScanAll(){var results=new List<ModuleScanResult>();foreach(var module in DefaultModules){results.Add(Scan(module));Thread.Sleep(1500);}return results;}
    private static IReadOnlyList<DtcEntry> ParseKwp2000DtcForScanner(Kwp2000Message response){if(response.Service==0x7F)throw new InvalidOperationException("KWP2000 negative response to DTC request.");if(response.Service!=0x58)throw new InvalidOperationException($"Expected KWP2000 DTC positive 58, got {response.Service:X2}.");if(response.Body.Count==0)return Array.Empty<DtcEntry>();var count=response.Body[0];var result=new List<DtcEntry>();var pos=1;for(var i=0;i<count&&pos+2<response.Body.Count;i++){var hi=response.Body[pos++];var lo=response.Body[pos++];var st=response.Body[pos++];result.Add(new DtcEntry((hi<<8)|lo,st));}return result;}
    private static IReadOnlyList<(bool Even,int BitMs)> BuildWakeCandidates(ModuleSpec module){if(module.Address==0x03)return[(false,195),(false,200),(true,195),(true,200)];if(module.Address is 0x17 or 0x25)return[(false,195),(false,200)];if(module.Address==0x01)return[(false,195),(false,200)];return[(false,200),(false,195)];}
}
